{"command": "cat > /workspace/build_patterns.py << 'PYEOF'
import json

# Note mappings (instrument numbers)
# Drums (use 96+row for one-shot triggering, or just use instrument/sample mapping)
KICK = 1
SNARE = 2
HH = 3
HHO = 4

# Bass notes (one-shot samples mapped to C-2 = row 0, D-2 = row 2, etc.)
# In FT2: C-2 is row 0, C#2 is row 1, D-2 is row 2, etc.
# But we're using sample-based instruments, so we just use the instrument number
# and trigger at the appropriate row (note value)

# For sample-based instruments where each sample is one note:
# C2 = 24, D2 = 26, E2 = 28, F2 = 29, G2 = 31, A2 = 33, B2 = 35
# C3 = 36, D3 = 38, E3 = 40, F3 = 41, G3 = 43, A3 = 45, B3 = 47
# C4 = 48, D4 = 50, E4 = 52, F4 = 53, G4 = 55, A4 = 57, B4 = 59
# C5 = 60, D5 = 62, E5 = 64, F5 = 65, G5 = 67, A5 = 69, B5 = 71

# We'll use direct sample mapping:
# Instrument 5 = Bass C2, 6 = D2, 7 = E2, 8 = F2, 9 = G2, 10 = A2
# Instrument 11 = Lead C4, 12 = D4, etc.
# Instrument 19 = Arp C5, 20 = D5, etc.

# Note values for each sample
BASS_NOTES = {
    'C2': (5, 24), 'D2': (6, 26), 'E2': (7, 28), 'F2': (8, 29),
    'G2': (9, 31), 'A2': (10, 33)
}

LEAD_NOTES = {
    'C4': (11, 48), 'D4': (12, 50), 'E4': (13, 52), 'F4': (14, 53),
    'G4': (15, 55), 'A4': (16, 57), 'B4': (17, 59), 'C5': (18, 60)
}

ARP_NOTES = {
    'C5': (19, 60), 'D5': (20, 62), 'E5': (21, 64), 'F5': (22, 65),
    'G5': (23, 67), 'A5': (24, 69), 'B5': (25, 71)
}

# Note name to FT2 row mapping
NOTE_TO_ROW = {
    'C': 0, 'C#': 1, 'D': 2, 'D#': 3, 'E': 4, 'F': 5,
    'F#': 6, 'G': 7, 'G#': 8, 'A': 9, 'A#': 10, 'B': 11
}

def note(name, octave):
    """Convert note name and octave to FT2 row"""
    row = NOTE_TO_ROW[name] + (octave + 1) * 12
    return row

def build_pattern_commands():
    """Build all pattern cell commands"""
    commands = []

    # ===== PATTERN 0: Basic Beat =====
    # Kick on 0, 16, 32, 48
    # Snare on 16, 48
    # Hi-hat on every 4 rows (eighth notes)

    # Channel 0: Kick
    for r in [0, 16, 32, 48]:
        commands.append({
            "name": "pattern_set_cell",
            "arguments": {"pattern": 0, "row": r, "channel": 0, "note": 60, "instrument": KICK}
        })

    # Channel 1: Snare
    for r in [16, 48]:
        commands.append({
            "name": "pattern_set_cell",
            "arguments": {"pattern": 0, "row": r, "channel": 1, "note": 62, "instrument": SNARE}
        })

    # Channel 2: Hi-hat (8th notes)
    for r in range(0, 64, 4):
        commands.append({
            "name": "pattern_set_cell",
            "arguments": {"pattern": 0, "row": r, "channel": 2, "note": 63, "instrument": HH}
        })

    # ===== PATTERN 1: Bass Line =====
    # C minor progression: Cm - Fm - G - Cm
    bass_pattern = [
        (0, 'C2', 32), (16, 'C2', 16), (24, 'D2', 8),
        (32, 'F2', 24), (40, 'G2', 16),
        (48, 'C2', 16)
    ]

    for row, note_name, _ in bass_pattern:
        inst, note_row = BASS_NOTES[note_name]
        commands.append({
            "name": "pattern_set_cell",
            "arguments": {"pattern": 1, "row": row, "channel": 4, "note": note_row, "instrument": inst}
        })

    # ===== PATTERN 2: Lead Melody =====
    # Simple melody in C minor
    lead_pattern = [
        (0, 'C4'), (4, 'E4'), (8, 'G4'), (12, 'E4'),
        (16, 'F4'), (20, 'G4'), (24, 'A4'), (28, 'G4'),
        (32, 'E4'), (36, 'G4'), (40, 'C5'), (44, 'G4'),
        (48, 'F4'), (52, 'E4'), (56, 'D4'), (60, 'C4')
    ]

    for row, note_name in lead_pattern:
        inst, note_row = LEAD_NOTES[note_name]
        commands.append({
            "name": "pattern_set_cell",
            "arguments": {"pattern": 2, "row": row, "channel": 5, "note": note_row, "instrument": inst}
        })

    # ===== PATTERN 3: Arpeggio =====
    # Fast arp pattern: C5 - Eb5 - G5 - Bb5 (C minor 7)
    arp_pattern = [
        (0, 'C5'), (1, 'E5'), (2, 'G5'), (3, 'E5'),
        (4, 'C5'), (5, 'F5'), (6, 'G5'), (7, 'E5'),
        (8, 'C5'), (9, 'E5'), (10, 'G5'), (11, 'A5'),
        (12, 'G5'), (13, 'E5'), (14, 'C5'), (15, 'D5'),
        (16, 'E5'), (17, 'G5'), (18, 'C5'), (19, 'E5'),
        (20, 'F5'), (21, 'G5'), (22, 'A5'), (23, 'G5'),
        (24, 'C5'), (25, 'E5'), (26, 'G5'), (27, 'E5'),
        (28, 'F5'), (29, 'G5'), (30, 'C5'), (31, 'D5')
    ]

    # Repeat pattern for rows 32-63
    for i, (row, note_name) in enumerate(arp_pattern):
        inst, note_row = ARP_NOTES[note_name]
        commands.append({
            "name": "pattern_set_cell",
            "arguments": {"pattern": 3, "row": row + 32, "channel": 6, "note": note_row, "instrument": inst}
        })

    for row, note_name in arp_pattern:
        inst, note_row = ARP_NOTES[note_name]
        commands.append({
            "name": "pattern_set_cell",
            "arguments": {"pattern": 3, "row": row, "channel": 6, "note": note_row, "instrument": inst}
        })

    # ===== PATTERN 4: Full Beat with variation =====
    # More hi-hats
    for r in range(0, 64, 2):
        inst = HH if r % 4 != 0 else HHO
        commands.append({
            "name": "pattern_set_cell",
            "arguments": {"pattern": 4, "row": r, "channel": 2, "note": 63, "instrument": inst}
        })

    # Kick on every beat
    for r in [0, 8, 16, 24, 32, 40, 48, 56]:
        commands.append({
            "name": "pattern_set_cell",
            "arguments": {"pattern": 4, "row": r, "channel": 0, "note": 60, "instrument": KICK}
        })

    # Snare on 2 and 4
    for r in [16, 48]:
        commands.append({
            "name": "pattern_set_cell",
            "arguments": {"pattern": 4, "row": r, "channel": 1, "note": 62, "instrument": SNARE}
        })

    # ===== PATTERN 5: Bass variation =====
    bass_var = [
        (0, 'C2', 8), (8, 'C2', 8), (16, 'D2', 8), (24, 'E2', 8),
        (32, 'F2', 8), (40, 'G2', 8), (48, 'G2', 8), (56, 'A2', 8)
    ]
    for row, note_name, _ in bass_var:
        inst, note_row = BASS_NOTES[note_name]
        commands.append({
            "name": "pattern_set_cell",
            "arguments": {"pattern": 5, "row": row, "channel": 4, "note": note_row, "instrument": inst}
        })

    # ===== PATTERN 6: Breakdown (sparse) =====
    commands.append({
        "name": "pattern_set_cell",
        "arguments": {"pattern": 6, "row": 16, "channel": 0, "note": 60, "instrument": KICK}
    })
    commands.append({
        "name": "pattern_set_cell",
        "arguments": {"pattern": 6, "row": 48, "channel": 1, "note": 62, "instrument": SNARE}
    })

    # Sparse lead
    commands.append({
        "name": "pattern_set_cell",
        "arguments": {"pattern": 6, "row": 0, "channel": 5, "note": 48, "instrument": 11}  # C4
    })
    commands.append({
        "name": "pattern_set_cell",
        "arguments": {"pattern": 6, "row": 32, "channel": 5, "note": 60, "instrument": 18}  # C5
    })

    # ===== PATTERN 7: Final Build =====
    # All elements playing
    # Kick on every 8th
    for r in range(0, 64, 4):
        commands.append({
            "name": "pattern_set_cell",
            "arguments": {"pattern": 7, "row": r, "channel": 0, "note": 60, "instrument": KICK}
        })

    # Snare on every beat
    for r in [8, 16, 24, 40, 48, 56]:
        commands.append({
            "name": "pattern_set_cell",
            "arguments": {"pattern": 7, "row": r, "channel": 1, "note": 62, "instrument": SNARE}
        })

    # Hi-hats
    for r in range(0, 64, 2):
        inst = HH
        commands.append({
            "name": "pattern_set_cell",
            "arguments": {"pattern": 7, "row": r, "channel": 2, "note": 63, "instrument": inst}
        })

    # Bass
    for row, note_name, _ in bass_pattern:
        inst, note_row = BASS_NOTES[note_name]
        commands.append({
            "name": "pattern_set_cell",
            "arguments": {"pattern": 7, "row": row, "channel": 4, "note": note_row, "instrument": inst}
        })

    # Lead
    for row, note_name in lead_pattern:
        inst, note_row = LEAD_NOTES[note_name]
        commands.append({
            "name": "pattern_set_cell",
            "arguments": {"pattern": 7, "row": row, "channel": 5, "note": note_row, "instrument": inst}
        })

    # Arp
    for row, note_name in arp_pattern:
        inst, note_row = ARP_NOTES[note_name]
        commands.append({
            "name": "pattern_set_cell",
            "arguments": {"pattern": 7, "row": row, "channel": 6, "note": note_row, "instrument": inst}
        })

    return commands

commands = build_pattern_commands()
with open('/workspace/patterns.json', 'w') as f:
    json.dump(commands, f)

print(f"Generated {len(commands)} pattern commands")
